<?php
declare(strict_types=1);
require_once __DIR__.'/includes/public-site.php';
require_once __DIR__.'/includes/menu-manager-core.php';
require_once __DIR__.'/includes/location-core.php';
require_once __DIR__.'/includes/media-core.php';
$context=public_site_fallback_context();$pdo=null;$selectedLocation=null;$locationCover='';
try{
    $pdo=app_pdo();$context=public_site_context($pdo);$org=(int)$context['organizationId'];
    if($org>0&&menu_manager_ready($pdo))$context['menuSections']=media_schema_ready($pdo)?media_public_menu_sections($pdo,$org):menu_manager_public_sections($pdo,$org);
    if($org>0){$locations=location_list($pdo,$org,false);$selectedLocation=location_selected($locations);if(!$selectedLocation)$selectedLocation=$locations[0]??null;if($selectedLocation&&media_schema_ready($pdo))$locationCover=media_location_cover_map($pdo,$org)[(int)$selectedLocation['id']]??'';}
}catch(Throwable $e){error_log('Public menu load failed: '.$e->getMessage());}
$settings=$context['settings'];
$sections=array_values(array_filter($context['menuSections'],static function(array $section):bool{$id=mb_strtolower((string)($section['id']??''),'UTF-8');$name=mb_strtolower((string)($section['name']??''),'UTF-8');return !str_contains($id,'gelato')&&!str_contains($name,'gelato');}));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0b09"><title>Menu | <?=app_escape((string)$settings['restaurant_name'])?></title><link rel="stylesheet" href="assets/css/site.css?v=20260914-2"><link rel="stylesheet" href="assets/css/page-headers.css?v=20260914-1"><link rel="stylesheet" href="assets/css/canonical-media.css?v=20260915-1"><style>.menu-item-image-layout{display:grid;grid-template-columns:150px minmax(0,1fr) auto;gap:18px;align-items:start}.menu-item-image-layout.no-image{grid-template-columns:minmax(0,1fr) auto}.ingredient-detail-row{display:flex;flex-wrap:wrap;gap:7px;margin-top:11px}.ingredient-image-chip{padding:4px 7px;border:1px solid rgba(255,255,255,.1);border-radius:8px;font-size:11px}@media(max-width:700px){.menu-item-image-layout,.menu-item-image-layout.no-image{grid-template-columns:1fr}.public-menu-item-image{width:100%;height:auto}.menu-price{justify-self:start}}</style></head><body class="page-menu"><?php public_site_render_header($settings,'menu');?><main class="page-main"><section class="page-hero"><div class="shell"><div class="eyebrow">Current Restaurant Menu</div><h1>Pizza, Food + Drinks.</h1><p>This menu is shared across Stonefellows locations.<?php if($selectedLocation):?> You are viewing the <?=app_escape((string)$selectedLocation['name'])?> location.<?php endif;?></p><?php if($locationCover!==''):?><img class="public-menu-location-cover" src="<?=app_escape($locationCover)?>" alt="<?=app_escape((string)$selectedLocation['name'])?>"><?php endif;?><?php if($context['dataMessage']!==''):?><div class="data-note"><?=app_escape((string)$context['dataMessage'])?></div><?php endif;?></div></section><section class="section"><div class="shell menu-sections"><?php if($sections):foreach($sections as $section):?><section class="menu-section" id="<?=app_escape((string)$section['id'])?>"><div class="menu-section-head"><div><div class="eyebrow">Menu</div><h2><?=app_escape((string)$section['name'])?></h2></div><?php if(trim((string)($section['intro']??''))!==''):?><p><?=app_escape((string)$section['intro'])?></p><?php endif;?></div><?php $items=is_array($section['items']??null)?$section['items']:[];if($items):?><div class="menu-list"><?php foreach($items as $item):$image=trim((string)($item['imageUrl']??''));$details=is_array($item['ingredientDetails']??null)?$item['ingredientDetails']:[];?><article class="menu-item"><div class="menu-item-image-layout<?=$image===''?' no-image':''?>"><?php if($image!==''):?><img class="public-menu-item-image" src="<?=app_escape($image)?>" alt="<?=app_escape((string)$item['name'])?>"><?php endif;?><div><h3><?=app_escape((string)$item['name'])?></h3><?php if(trim((string)$item['description'])!==''):?><p><?=app_escape((string)$item['description'])?></p><?php endif;?><?php if($details):?><div class="ingredient-detail-row"><?php foreach($details as $ingredient):?><span class="ingredient-image-chip"><?php if(!empty($ingredient['imageUrl'])):?><img src="<?=app_escape((string)$ingredient['imageUrl'])?>" alt=""><?php endif;?><?=app_escape((string)$ingredient['name'])?></span><?php endforeach;?></div><?php elseif(!empty($item['ingredients'])):?><div class="ingredients"><?=app_escape(implode(' · ',array_map('strval',$item['ingredients'])))?></div><?php endif;?></div><?php $price=public_site_price($item);?><div class="menu-price"><?=$price!==''?app_escape($price):''?></div></div></article><?php endforeach;?></div><?php else:?><div class="empty-state">No active items are published in this section.</div><?php endif;?></section><?php endforeach;else:?><div class="empty-state">The active restaurant menu is not available yet.</div><?php endif;?></div></section></main><?php public_site_render_footer($settings);?><script src="assets/js/site.js?v=20260914"></script><script src="assets/js/public-shell.js?v=20260915-1"></script></body></html>
